public sealed class BossSweepTests{
 string folder;GameClient c;bool background;Boss_manager M=>c.BossMode;
 void Independent(Scene scene,LoadSceneMode mode){if(scene.name=="GameClient")scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<GameClient>(true)).Single().SaveFolderOverride=folder;}
 [UnitySetUp]public IEnumerator Setup(){background=Application.runInBackground;Application.runInBackground=true;folder=Path.Combine(Application.temporaryCachePath,"BossSweep-"+Guid.NewGuid().ToString("N"));SceneManager.sceneLoaded+=Independent;yield return TestSceneLoader.LoadAsync("GameClient");yield return ClientStartupWait.Ready();c=GameClient.Instance;ForestRuntimeAcceptance.IsGaming=false;}
 [UnityTearDown]public IEnumerator Cleanup(){yield return TestSceneLoader.LoadAsync("TargetPreview");SceneManager.sceneLoaded-=Independent;Time.timeScale=1;Application.runInBackground=background;if(Directory.Exists(folder))Directory.Delete(folder,true);}
 void Page(){c.DailyLogin.Close();c.Tutorial.SetCleared();ContentNavigationFixture.Unlock(c,Content_Type.Boss);UnityEngine.Object.FindAnyObjectByType<Alert>(FindObjectsInactive.Include)?.gameObject.SetActive(false);M.StartPanel_Open();}
 void Powered(){Assert.That(c.LocalStore.Model.Apply("catgunner_pluspack_2"),Is.True);c.State.Owned_Gun_list[0]=20;Assert.That(c.Inventory.Equip(0,0),Is.True);Page();Assert.That(M.is_SweepAble(),Is.True,"Original Gun20 power fixture");}
 static string Report(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports",name));
 IEnumerator Capture(string name){ScreenCapture.CaptureScreenshot(Report("visual/boss-sweep-"+name+"-gpu.png"));yield return new WaitForSeconds(.2f);}
 Button SweepButton=>M.Start_UI.Auto_obj.GetComponentsInChildren<Button>(true).Single(b=>Enumerable.Range(0,b.onClick.GetPersistentEventCount()).Any(i=>b.onClick.GetPersistentMethodName(i)=="Game_Sweep"));
    IEnumerator Click(Button button)
    {
        yield return new WaitForSecondsRealtime(.5f);Assert.That(button.gameObject.activeInHierarchy&&button.enabled&&button.interactable,Is.True,button.name);Canvas.ForceUpdateCanvases();
        var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;
        int clicks=0;void Observe()=>clicks++;button.onClick.AddListener(Observe);
        try
        {
            var rect=(RectTransform)button.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));
            // Allow the input module to activate and observe neutral movement
            // before the one-frame down/up sequence after scene registration.
            yield return null;yield return null;
            var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=mouse.Position},hits);
            Assert.That(ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits.FirstOrDefault().gameObject)?.GetComponent<Button>(),Is.SameAs(button),string.Join("|",hits.Take(4).Select(x=>x.gameObject.name)));
            var pointerMethod=typeof(PointerInputModule).GetMethod("GetLastPointerEventData",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
            Assert.That(pointerMethod,Is.Not.Null);
            PointerEventData Pointer()=>pointerMethod.Invoke(module,new object[]{-1}) as PointerEventData;
            mouse.Down=mouse.Held=true;float deadline=Time.realtimeSinceStartup+1;
            do{yield return null;}while(Pointer()?.pointerPress!=button.gameObject&&Time.realtimeSinceStartup<deadline);
            Assert.That(Pointer()?.pointerPress,Is.SameAs(button.gameObject),"input module must observe source pointer press before release");
            mouse.Down=mouse.Held=false;mouse.Up=true;deadline=Time.realtimeSinceStartup+1;
            do{yield return null;}while(clicks==0&&Time.realtimeSinceStartup<deadline);
            mouse.Up=false;yield return null;
            Assert.That(clicks,Is.EqualTo(1),button.name+" actual onClick reception");
        }
        finally{button.onClick.RemoveListener(Observe);module.inputOverride=null;UnityEngine.Object.Destroy(mouse);}
    }
