 [UnityTest]public IEnumerator OriginalSweepAndBonusButtonsAdvanceOnceCreditTripleAndColdReload(){Powered();yield return new WaitForSeconds(.7f);int dia=c.State.Dia,earned=c.State._getDia,forestStage=c.Forest.Stage_Now;yield return Click(SweepButton);Assert.That((M.Stage_Now,c.State.Boss_Stage,c.Mode),Is.EqualTo((1,1,0)));Assert.That(c.State.Dia,Is.EqualTo(dia+150));Assert.That(M.GameSweep_UI.activeInHierarchy,Is.True);Assert.That(M.SweepBonus_Btn_obj.activeSelf&&M.SweepSkip_obj.activeSelf,Is.True);Assert.That(M.SweepNoAds_Btn_obj.activeSelf,Is.False);M.Game_Sweep();M.SweepBonus_Get();Assert.That(c.State.Dia,Is.EqualTo(dia+150));yield return new WaitForSeconds(1.7f);yield return Capture("base-result");Assert.That(M.SweepBonus_Btn_obj.GetComponent<Button>().onClick.GetPersistentMethodName(0),Is.EqualTo("Bonus_AD_Show"));yield return Click(M.SweepBonus_Btn_obj.GetComponent<Button>());yield return null;Assert.That(c.State.Dia,Is.EqualTo(dia+450));Assert.That(c.State._getDia,Is.EqualTo(earned+1350));Assert.That(c.RewardedAds.CompletedWatches,Is.EqualTo(1));Assert.That(M.SweepPending||M.GameSweep_UI.activeSelf,Is.False);Assert.That(c.Forest.Stage_Now,Is.EqualTo(forestStage));c.SaveNow();yield return TestSceneLoader.LoadAsync("TargetPreview");yield return TestSceneLoader.LoadAsync("GameClient");yield return ClientStartupWait.Ready();c=GameClient.Instance;Assert.That((M.Stage_Now,c.State.Dia),Is.EqualTo((1,dia+450)));Assert.That(M.SweepPending||M.GameSweep_UI.activeSelf,Is.False);Assert.That(c.LocalStore.Model.Recorded("catgunner_pluspack_2"),Is.True);}
 [UnityTest]public IEnumerator CancelledDisabledDuplicateAndClosedAdCallbacksCannotGrant(){Powered();M.Game_Sweep();int dia=c.State.Dia;c.RewardedAds.Enabled=false;M.Bonus_AD_Show();yield return null;Assert.That(c.State.Dia,Is.EqualTo(dia));c.RewardedAds.Enabled=true;M.Bonus_AD_Show();M.Bonus_AD_Show();c.RewardedAds.Cancel();yield return null;Assert.That(c.State.Dia,Is.EqualTo(dia));M.Bonus_AD_Show();M.Sweep_Close();yield return null;yield return null;Assert.That(c.State.Dia,Is.EqualTo(dia));Assert.That(c.RewardedAds.CompletedWatches,Is.Zero);M.Game_Sweep();int second=c.State.Dia;M.Bonus_AD_Show();M.Bonus_AD_Show();yield return null;yield return null;Assert.That(c.State.Dia,Is.EqualTo(second+300));Assert.That(c.RewardedAds.CompletedWatches,Is.EqualTo(1));M.Bonus_Get();Assert.That(c.State.Dia,Is.EqualTo(second+300));}
 [UnityTest]public IEnumerator ForcedAdRemovalIsOrdinaryAndFullRemovalAutoCreditsWithPlusReward(){Powered();Assert.That(c.LocalStore.Model.Apply("remove_forced_ads"),Is.True);int dia=c.State.Dia;M.Game_Sweep();Assert.That(M.AutoReward,Is.False);Assert.That(c.State.Dia,Is.EqualTo(dia+150));M.Sweep_Close();Assert.That(c.LocalStore.Model.Apply("remove_all_ads"),Is.True);Assert.That(c.LocalStore.Model.Apply("catgunner_pluspack_1"),Is.True);M.Game_Sweep();Assert.That(M.RunReward,Is.EqualTo(300));Assert.That(c.State.Dia,Is.EqualTo(dia+1050));Assert.That(M.SweepNoAds_Btn_obj.activeSelf,Is.True);Assert.That(M.SweepBonus_Btn_obj.activeSelf||M.SweepSkip_obj.activeSelf,Is.False);yield return new WaitForSeconds(1.7f);yield return Capture("automatic-result");yield return Click(M.SweepNoAds_Btn_obj.GetComponent<Button>());Assert.That(M.SweepPending||M.GameSweep_UI.activeSelf,Is.False);Assert.That(c.RewardedAds.CompletedWatches,Is.Zero);Assert.That(c.State.PurchaseHistory,Is.Empty);Assert.That(c.State.ProcessedTxnIds,Is.Empty);}
