public sealed class BossSweepRulesTests{
 [Test]public void NativeRequiredPowerRoundsSecondsToEvenAndTruncatesFiveDigits(){var h=new DecimalAmount(50000);Assert.That(BossSweepRules.RequiredPower(h,60).CompareTo(new DecimalAmount(11904,-1)),Is.Zero);Assert.That(BossSweepRules.RequiredPower(h,120).CompareTo(new DecimalAmount(59523,-2)),Is.Zero);Assert.That(BossSweepRules.RequiredPower(new DecimalAmount(100),15).CompareTo(new DecimalAmount(10)),Is.Zero);Assert.That(BossSweepRules.RequiredPower(h,0).CompareTo(h),Is.Zero);}
 [Test]public void NativePercentClampsAndCentisecondQuantizationIsRetained(){Assert.That(BossSweepRules.FillPercent(new DecimalAmount(999),new DecimalAmount(1000)),Is.EqualTo(99));Assert.That(BossSweepRules.FillPercent(new DecimalAmount(0),new DecimalAmount(1000)),Is.Zero);Assert.That(BossSweepRules.FillPercent(new DecimalAmount(1000),new DecimalAmount(1000)),Is.EqualTo(100));Assert.That(BossSweepRules.FillPercent(new DecimalAmount(1),new DecimalAmount(0)),Is.EqualTo(100));Assert.That(BossSweepRules.Dps(new DecimalAmount(100),.359f).CompareTo(BossSweepRules.Divide(new DecimalAmount(10000),35)),Is.Zero);Assert.That(BossSweepRules.Dps(new DecimalAmount(100),.001f).Coefficient.Sign,Is.Zero);}
 [Test]public void ExpectedDamageDiscardsBeforeBuffAndCriticalAndClampsChance(){var baseGun=new DecimalAmount(109,-1);Assert.That(BossSweepRules.ExpectedDamage(baseGun,new DecimalAmount(100),100,0,new DecimalAmount(100),4,0,0,new DecimalAmount(100),50).CompareTo(new DecimalAmount(45)),Is.Zero);Assert.That(BossSweepRules.ExpectedDamage(baseGun,new DecimalAmount(100),100,0,new DecimalAmount(100),1,0,0,new DecimalAmount(100),200).CompareTo(new DecimalAmount(12)),Is.Zero);}
